package net.minecraft.world.entity.player;
import dev.zomboidmelee.boxing.Checks16.*;
public class Player{public Stack main=new Stack(true),off=new Stack(true);public World world=new World();public float swing;public boolean alive=true,spectator,sleeping,using;public double x=5,y=7,z=9;public int swings;public Stack getMainHandItem(){return main;}public Stack getOffhandItem(){return off;}public boolean isAlive(){return alive;}public boolean isSpectator(){return spectator;}public boolean isSleeping(){return sleeping;}public boolean isUsingItem(){return using;}public float getAttackAnim(float p){return swing;}public void swing(net.minecraft.world.InteractionHand hand){swings++;}public World level(){return world;}}
